// Tabela oficial de motivos de perda (nomes e ids do Flow CRM)
const MOTIVOS = {
  'Sem resposta':           '40383d24-d479-4a5e-b4e0-de71497aa3db',
  'Perdeu interesse':       'd57f4002-2bb5-41aa-92fa-c4657c07a0f5',
  'Recusou a reunião':      '4e32430f-bd87-4268-9036-1a8dbf379568',
  'Sem orçamento':          '8e83765b-baf7-471f-9edd-b52254cf5871',
  'Preço alto':             'e4b19b33-50c1-4d59-8d01-1fc612e250e1',
  'Timing ruim':            'f838d18c-3242-448a-84a8-eceb4c1556c7',
  'Escolheu outra solução': 'e956070c-9a5d-4a6c-96e3-44d39cbe3aff',
  'Concorrência':           '3403117f-6bac-448c-a70a-eaab14b3f5c9',
  'Fora do perfil':         '5ab5aa21-1be6-4e42-ac5e-a9ca8e437cb2',
  'Contato inválido':       '908037f7-4726-47da-be28-eda3909d1f80',
  // Este é enviado pelo nome (o Flow acha o id)
  'Pediu para não ser contatado': 'por_nome'
};
// Motivos que são da PESSOA (não da empresa): marca só o contato; a empresa só é perdida
// se não sobrar nenhum contato ativo.
const MOTIVOS_DA_PESSOA = ['Pediu para não ser contatado', 'Contato inválido'];

const e = $input.first().json;
const motivo = String(e.motivo || '').trim();
let etapa = String(e.etapa || '').trim();
// "Agora não / mais pra frente" não é perda: vai para a Geladeira (lead com potencial, momento errado)
if (etapa === 'Lead Perdido' && motivo === 'Timing ruim') etapa = 'Geladeira';

return [{
  json: {
    ...e,
    etapa,
    motivo,
    motivo_id: etapa === 'Lead Perdido' ? (MOTIVOS[motivo] || null) : null,
    comentario: String(e.comentario || '').trim(),
    telefone: String(e.telefone || '').replace(/\D/g, ''),
    pedido_nao_contatar: etapa === 'Lead Perdido' && MOTIVOS_DA_PESSOA.includes(motivo)
  }
}];

// Lead Perdido: marca como perdido só os contratos abertos que estão nas etapas da prospecção/SDR.
// Contratos em outras etapas (proposta, geladeira etc.) são outras negociações da mesma empresa e NÃO são tocados.
const FLOW = 'https://vclwmydunloeqomsmaah.supabase.co/functions/v1/api-v1';
const H = { Authorization: '***REMOVIDO***', 'Content-Type': 'application/json' };
const ETAPAS_SDR = ['Prospecção', 'Disparo Inicial', 'Follow-up', 'Agendar reunião', 'Reunião'];
const p = $('Preparar motivo').first().json;
const leadId = $('Mover etapa').first().json.lead_id;
const etapas = (await this.helpers.httpRequest({ method: 'GET', url: FLOW + '/pipeline-stages', headers: H, json: true })).items || [];
const idsSdr = new Set(etapas.filter(e => ETAPAS_SDR.includes(e.name)).map(e => e.id));
const r = await this.helpers.httpRequest({ method: 'GET', url: FLOW + '/leads/' + leadId + '/contracts', headers: H, json: true });
const abertos = (r.contracts || []).filter(c => c.status === 'negociando');
// Contratos sem etapa também contam (contrato criado agora para registrar a perda)
const alvo = abertos.filter(c => !c.stage_id || idsSdr.has(c.stage_id));
if (!alvo.length) throw new Error('nenhum contrato em negociação nas etapas da prospecção');
const motivo = p.motivo_id === 'por_nome' ? { loss_reason: p.motivo } : { loss_reason_id: p.motivo_id };
for (const c of alvo) {
  await this.helpers.httpRequest({ method: 'POST', url: FLOW + '/leads/' + leadId + '/stage', headers: H, json: true, body: { stage_name: 'Lead Perdido', contract_id: c.id, loss_comment: p.comentario || p.motivo, ...motivo } });
}
return [{ json: { ok: true, contratos: alvo.length } }];
